from typing import Optional, TYPE_CHECKING

from requests import Session

from .client import BaseClient
from .schema_check import schema_check
from .schemas.rapi.surveys_schemas import (
    SurveyBeginResponseSchema,
    SurveyGetResponseSchema,
    SurveyVoteResponseSchema,
)

if TYPE_CHECKING:
    from pyvkteamsclient.client import DesktopClient


__all__ = ["MiniAppClient"]


class MiniAppClient(BaseClient):
    """
    Класс для обертки API
    """

    def __init__(
        self,
        session: Session,
        miniapps_api_url: str,
        account: "DesktopClient",
        env: str = "SANDBOX",
    ):
        BaseClient.__init__(
            self,
            session=session,
            miniapps_api_url=miniapps_api_url,
            account=account,
            env=env,
        )

    def __str__(self):
        return f"MiniAppClient(env={self.env}, account={self.account})"

    def __repr__(self):
        return f"MiniAppClient(env={self.env}, account={self.account})"

    @schema_check(SurveyBeginResponseSchema)
    def rapi_survey_begin(self, surveyId: str):
        """
        Начать прохождение/пройти еще раз - удаляет всю историю голосования
        пользователя,
        начинает фиксировать прохождение Опрос Про как первый раз.
        """
        return self.post(
            "Internal/survey/begin",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": surveyId},
            },
        )

    @schema_check(SurveyVoteResponseSchema)
    def rapi_survey_vote(self, surveyId: str, questionId: str, value):
        """
        Проголосовать/переголосовать (покрывает и revoke)
        по данному опросу на конкретный вопрос.
        """
        return self.post(
            "Internal/survey/vote",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "surveyId": surveyId,
                    "questionId": questionId,
                    "value": value,
                },
            },
        )

    @schema_check(SurveyGetResponseSchema)
    def rapi_survey_get(self, survey_id: str):
        """
        Получение всей имеющейся информации об опросе.
        """
        return self.post(
            "Internal/survey/get",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": survey_id},
            },
        )

    def internal_survey_create(
        self,
        sender_sn: str,
        name: str,
        image: str,
        description: Optional[str] = "Default description",
        stop: Optional[int] = None,
        thanks: Optional[str] = "Default thanks",
        forwarding: Optional[bool] = True,
        **kwargs,
    ):
        """
        Cоздать опрос
        Создает опроса. Возвращает идентификатор созданного опроса.
        :param sender_sn: SN пользователя, для которого будет создан опрос
        :param name: Имя опроса
        :param description: Описание опроса
        :param stop: установить время, дату завершения опроса UTC - unix time
        :param thanks: благодарность за участие
        :param forwarding: доступен для пересылки
        :param image: fileId файла изображения
        param flags: example: List ["anonymous"] List ["nonanonymous"] Флаги опроса (анонимное голосование)
        :return: тело ответа сервера
        """
        params = {
            "senderSn": sender_sn,
            "name": name,
            "description": description,
            "thanks": thanks,
            "forwarding": forwarding,
            "image": image,
            **kwargs,
        }

        if stop is not None:
            params["stop"] = stop

        return self.post(
            "internal/survey/create",
            json={"reqId": self.getReqId(), "params": params},
        )

    def internal_survey_update(self, sender_sn: str, survey_id: str, **kwargs):
        """
        Обновить параметры опроса
        Обновляет параметры опроса.
        :param sender_sn: SN пользователя, для которого будет создан опрос
        :param survey_id: идентификатор опроса
        param flags: example: List [ "anonymous" ] Флаги опроса (анонимное голосование)
        param name: Имя опроса
        param description: Описание опроса
        param stop: установить время, дату завершения опроса UTC - unix time
        param thanks: благодарность за участие
        param forwarding: доступен для пересылки
        param image: fileId файла изображения
        :return: тело ответа сервера
        """
        return self.post(
            "internal/survey/update",
            json={
                "reqId": self.getReqId(),
                "params": {
                    "senderSn": sender_sn,
                    "surveyId": survey_id,
                    **kwargs,
                },
            },
        )

