    def internal_survey_questions_create(self, sender_sn: str, survey_id: str, name: str, **kwargs):
        """
        Cоздать вопрос
        Создает параметры вопроса.
        :param senderSn: SN пользователя, для которого будут получены ссылки
        :param surveyId: идентификатор опроса
        :param name: example: Какой язык программирования вы предпочитаете? Название вопроса
        param number: minimum: 1 example: 5 Порядковый номер в опросе
        param typeQuestion: example: single Тип вопроса type (выбор из
        списка/шкала/открытый/булевый/удовлетворение) Enum: [ single, scale, open, yesNo, pleasure ]
        param flags: example: List [ "require", "many", "own_version" ] Флаги вопроса - обязательный вопрос,
        для single - выбор нескольких вариантов, задание собственного варианта Enum: [ require, many, own_version ]
        param values: { anyOf ->
        single[ title: single example: List [ "C++", "Java", "Golang", "Python" ] Варианты ответа - выбор из списка
        scale{ description: Шкала  example: List [ 1, "Не нравится!" ]
        open maxLength: 1000 example: Your personal variant Открытый
        yesNo example: false Варианты ответа - Да/Нет
        pleasure[title: pleasure example: List [ "'!-_-!' Совершенно удовлетворен", "!-_-! Удовлетворен",
        "!-_-! Не знаю", "!-_-! Не удовлетворен", "!-_-! Абсолютно не удовлетворен" ] Варианты ответа - шкала
        удовлетворения, множественный с заранее определенным набором смайлов
        :return: тело ответа сервера
        """
        return self.post(
            "internal/survey/questions/create",
            json={
                "reqId": self.getReqId(),
                "params": {
                    "senderSn": sender_sn,
                    "surveyId": survey_id,
                    "name": name,
                    **kwargs,
                },
            },
        )

