    def internal_survey_targets_del(
        self,
        sender_sn: str,
        survey_id: str,
        sn_list: Optional[list] = None,
        sn_all: Optional[bool] = False,
    ):
        """
        Удаление пользователей из списка целей (возможных респондентов)
        :param sender_sn: SN пользователя, для которого будут получены ссылки
        :param survey_id: идентификатор опроса
        :param sn_list: массив sn-ов пользователей для удаления
        :param sn_all: true, удалить все targets, взаимоисключающее с list, или list или all:true
        :return: тело ответа сервера
        """
        params = {
            "senderSn": sender_sn,
            "surveyId": survey_id,
        }
        if sn_all:
            params["all"] = True
        else:
            params["list"] = sn_list

        return self.post(
            "internal/survey/targets/del",
            json={
                "reqId": self.getReqId(),
                "params": params,
            },
        )

