    def internal_avatar_get(self, size: int, target_sn: Optional[str] = None, target_nick: Optional[str] = None):
        """
        Получение аватара пользователя или чата
        Необходимо передать в запросе ровно один из параметров 'targetSn' или 'targetNick'
        :param target_sn: sn пользователя или чата, для которого запрашивается аватар.
        :param target_nick: nick пользователя или чата, для которого запрашивается аватар
        :param size: Размер аватара [64, 128, 256, 1024]
        :return: тело ответа сервера
        """
        params = {"size": size}

        if target_sn:
            params["targetSn"] = target_sn
        elif target_nick:
            params["targetNick"] = target_nick

        return self.post(
            "internal/avatar/get",
            json={
                "reqId": self.getReqId(),
                "params": params,
            },
        )

    def internal_contacts_get(
        self,
        nobot: Optional[bool] = False,
        nodeleted: Optional[bool] = False,
    ):
        """
        Получение аватара пользователя или чата
        Необходимо передать в запросе ровно один из параметров 'targetSn' или 'targetNick'
        :param nobot: Показывать ботов
        :param nodeleted: Показывать удаленные
        :return: тело ответа сервера
        """
        return self.post(
            "internal/contacts/get",
            json={
                "reqId": self.getReqId(),
                "params": {"nobot": nobot, "nodeleted": nodeleted},
            },
        )

    def clean_survey_list(self):
        response = self.internal_survey_list(sender_sn=self.account.uin)

        errors_list = []

        for survey in response["results"]["surveys"]:
            try:
                self.internal_survey_stop(sender_sn=self.account.uin, survey_id=survey["surveyId"])
                self.internal_survey_delete(sender_sn=self.account.uin, survey_id=survey["surveyId"])
            except Exception as error:
                errors_list.append(error)

        if errors_list:
            raise ExceptionGroup(f"Cleaning {self.account.uin} surveys failed", errors_list)  # noqa: F821
